# qpecgen.mod QQR2-MN-v-v
# Original AMPL coding by Sven Leyffer, University of Dundee, Feb 2001.
#
# AMPL file which implements QPs generated by QPECgen.
#
# Reference: H. Jiang and D. Ralph, "QPECgen: A MATLAB generator for
# mathematical programs with quadratic objectives and affine variational
# inequality constraints", Computational Optimization and Applications.
#
# The problems generated here are LCP constrained QPs (i.e. type 300)
# of the form
#
#	min	0.5*(x,y)'*P*(x,y) + c'x + d'y
#	s.t.	A*(x,y) + a <= 0		(1)
#		F(x,y) = N*x + M*y + q >= 0
#		y >= 0
#		F(x,y)*y = 0

using JuMP

function build_model(n_x::Int, n_y::Int, m_1::Int, Pxx, Pxy, Pyy, c_vec, d_vec, Ax, Ay, a_vec, N_mat, M_mat, q_vec)
    model = Model()

    @variable(model, x[1:n_x])
    @variable(model, y[1:n_y] >= 0)

    @objective(model, Min,
        0.5 * sum(x[i] * sum(Pxx[i,j]*x[j] for j in 1:n_x) for i in 1:n_x)
        + 0.5 * sum(y[i] * sum(Pyy[i,j]*y[j] for j in 1:n_y) for i in 1:n_y)
        + sum(x[i] * sum(Pxy[i,j]*y[j] for j in 1:n_y) for i in 1:n_x)
        + sum(x[i]*c_vec[i] for i in 1:n_x)
        + sum(y[i]*d_vec[i] for i in 1:n_y))

    @constraint(model, Acon[i in 1:m_1],
        sum(Ax[i,j]*x[j] for j in 1:n_x)
        + sum(Ay[i,j]*y[j] for j in 1:n_y)
        + a_vec[i] <= 0)

    @variable(model, Fcon_s[1:n_y] >= 0)
    @constraint(model, Fcon_def[i in 1:n_y],
        Fcon_s[i] == q_vec[i] + sum(N_mat[i,j]*x[j] for j in 1:n_x) + sum(M_mat[i,j]*y[j] for j in 1:n_y))
    @constraint(model, Fcon[i in 1:n_y], [y[i], Fcon_s[i]] in SOS1())

    return model
end
